<template>
  <div class="screen-page" :class="{ 'is-fullscreen': isFullscreen }">
    <div class="screen-stage">
      <header class="screen-header">
        <div class="header-line left" />
        <div class="header-title"><span class="title-mark" />智能运维综合态势大屏<span class="title-mark right" /></div>
        <div class="header-meta"><span class="live-dot" />实时监测 <b>{{ clock }}</b></div>
        <button class="screen-control" type="button" @click="toggleFullscreen">{{ isFullscreen ? '退出全屏' : '全屏展示' }}</button>
      </header>

      <div class="screen-tabs">
        <span class="tab active">2026-09</span><span class="tab">全域</span><span class="tab">运维资产</span><span class="tab spacer" /><span class="tab">知识库规则</span><span class="tab">数字员工</span>
      </div>

      <main class="screen-body">
        <section class="screen-column left-column">
          <ScreenPanel title="资产健康排行" subtitle="HEALTH RANKING">
            <div ref="assetChartRef" class="panel-chart bar-chart" />
          </ScreenPanel>
          <ScreenPanel title="告警与任务态势" subtitle="ACTIVE EVENTS">
            <div class="rank-list">
              <div v-for="(row, index) in alertRanking" :key="row.name" class="rank-row"><i>{{ index + 1 }}</i><span>{{ row.name }}</span><b>{{ row.value }}</b><em :style="{ width: `${row.percent}%` }" /></div>
              <div v-if="!alertRanking.length" class="empty-line">当前无活动异常</div>
            </div>
          </ScreenPanel>
          <ScreenPanel title="资产清单" subtitle="ASSET INVENTORY">
            <div class="mini-table"><div class="table-head"><span>主机</span><span>业务</span><span>状态</span></div><div v-for="asset in assets.slice(0, 5)" :key="asset.hostname" class="table-row"><span>{{ asset.hostname }}</span><span>{{ asset.app || '—' }}</span><b :class="asset.reachable ? 'ok' : 'bad'">{{ asset.reachable ? '在线' : '异常' }}</b></div><div v-if="!assets.length" class="empty-line">暂无资产数据</div></div>
          </ScreenPanel>
        </section>

        <section class="screen-column center-column">
          <div class="metric-row"><MetricCard icon="▣" :value="kpis.asset_total" label="纳管资产" unit="台" tone="cyan" /><MetricCard icon="◉" :value="kpis.asset_reachable" label="当前可达" unit="台" tone="green" /><MetricCard icon="⚠" :value="kpis.active_anomalies" label="活动告警" unit="条" tone="orange" /><MetricCard icon="✓" :value="kpis.open_tickets" label="进行中任务" unit="单" tone="violet" /></div>
          <div class="center-map-panel"><div class="center-panel-title"><span>基础设施运行态势</span><small>INFRASTRUCTURE TOPOLOGY</small></div><div class="topology"><div class="orbit orbit-one" /><div class="orbit orbit-two" /><div class="core-node"><strong>{{ kpis.availability }}%</strong><span>综合可达率</span></div><div v-for="(asset, index) in assets.slice(0, 8)" :key="asset.hostname" class="asset-node" :class="{ warning: !asset.reachable }" :style="nodeStyle(index, assets.slice(0, 8).length)"><i /><strong>{{ shortName(asset.hostname) }}</strong><small>{{ asset.app || '运维节点' }}</small></div></div><div class="topology-legend"><span><i class="green-dot" />健康</span><span><i class="yellow-dot" />关注</span><span><i class="red-dot" />异常</span></div></div>
          <ScreenPanel title="运维风险预警" subtitle="RISK ALERTS"><div class="risk-grid"><div v-for="(alert, index) in alerts.slice(0, 6)" :key="`${alert.hostname}-${index}`" class="risk-card" :class="severityClass(alert.severity)"><b>{{ index + 1 }}</b><span>{{ shortName(alert.hostname || '系统事件') }}</span><small>{{ alert.trigger || alert.message || '异常事件' }}</small></div><div v-if="!alerts.length" class="risk-clear"><span>✓</span>当前无活动风险预警</div></div></ScreenPanel>
        </section>

        <section class="screen-column right-column">
          <ScreenPanel title="近 7 日告警趋势" subtitle="EVENT TREND"><div ref="trendChartRef" class="panel-chart line-chart" /></ScreenPanel>
          <ScreenPanel title="资产状态分布" subtitle="HEALTH DISTRIBUTION"><div class="distribution"><div ref="pieChartRef" class="pie-chart" /><div class="distribution-legend"><span><i class="legend-green" />在线 <b>{{ kpis.asset_reachable }}</b></span><span><i class="legend-red" />异常 <b>{{ kpis.asset_total - kpis.asset_reachable }}</b></span><span><i class="legend-blue" />综合可达率 <b>{{ kpis.availability }}%</b></span></div></div></ScreenPanel>
          <ScreenPanel title="数字员工闭环指标" subtitle="DIGITAL EMPLOYEE"><div class="employee-summary"><div><strong>{{ kpis.recovered_tickets }}</strong><span>已恢复任务</span></div><div><strong>{{ kpis.open_tickets }}</strong><span>待处理任务</span></div><div><strong>{{ knowledgeCount }}</strong><span>知识文档</span></div></div><div class="employee-tip"><span class="ai-pulse">AI</span><div><b>DevOpsAgent 在线守护</b><small>基于企业规则进行分析与建议</small></div></div></ScreenPanel>
        </section>
      </main>
      <footer class="screen-footer"><span>DEVOPS AGENT · 智能运维数字员工</span><span>数据更新时间：{{ updatedAt }} · 自动刷新 30 秒</span></footer>
    </div>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import * as echarts from 'echarts'
import { ElMessage } from 'element-plus'
import { fetchDashboardOverview, fetchKnowledgeDocuments } from '../api'

const overview = ref({ kpis: {}, trend: [], assets: [], anomalies: [] })
const knowledgeCount = ref(0)
const clock = ref('')
const updatedAt = ref('—')
const isFullscreen = ref(false)
const assetChartRef = ref(null); const trendChartRef = ref(null); const pieChartRef = ref(null)
let assetChart; let trendChart; let pieChart; let refreshTimer; let clockTimer

const kpis = computed(() => overview.value.kpis || {})
const assets = computed(() => overview.value.assets || [])
const alerts = computed(() => overview.value.anomalies || [])
const alertRanking = computed(() => alerts.value.map((item) => ({ name: item.hostname || item.trigger || '未知事件', value: item.severity || '关注', percent: 70 })).slice(0, 6))

function updateClock() { clock.value = new Date().toLocaleString('zh-CN', { hour12: false }) }
function shortName(value) { const text = String(value || '未知'); return text.length > 12 ? `${text.slice(0, 12)}…` : text }
function severityClass(value) { const text = String(value || '').toLowerCase(); return text.includes('high') || text.includes('高') ? 'danger' : text.includes('warning') || text.includes('中') ? 'warning' : 'normal' }
function nodeStyle(index, total) { const angle = (Math.PI * 2 * index) / Math.max(total, 1) - Math.PI / 2; const radiusX = 38; const radiusY = 37; return { left: `${50 + Math.cos(angle) * radiusX}%`, top: `${50 + Math.sin(angle) * radiusY}%` } }
async function load() { try { const [dashboard, docs] = await Promise.all([fetchDashboardOverview(), fetchKnowledgeDocuments()]); overview.value = dashboard.data; knowledgeCount.value = docs.data.total || 0; updatedAt.value = new Date().toLocaleTimeString('zh-CN', { hour12: false }); await nextTick(); drawCharts() } catch (error) { ElMessage.error(error.response?.data?.detail || '独立大屏数据加载失败') } }
function drawCharts() {
  const textColor = '#89a8ca'; const gridColor = 'rgba(105, 153, 207, .18)';
  assetChart?.dispose(); trendChart?.dispose(); pieChart?.dispose();
  assetChart = assetChartRef.value && echarts.init(assetChartRef.value); trendChart = trendChartRef.value && echarts.init(trendChartRef.value); pieChart = pieChartRef.value && echarts.init(pieChartRef.value);
  assetChart?.setOption({ grid: { left: 30, right: 15, top: 16, bottom: 30 }, xAxis: { type: 'category', data: assets.value.slice(0, 8).map((item) => shortName(item.hostname)), axisLabel: { color: textColor, fontSize: 10, rotate: 26 }, axisLine: { lineStyle: { color: gridColor } } }, yAxis: { type: 'value', minInterval: 1, splitLine: { lineStyle: { color: gridColor } }, axisLabel: { color: textColor, fontSize: 10 } }, series: [{ type: 'bar', barWidth: 18, data: assets.value.slice(0, 8).map((item) => item.reachable ? 100 : 36), itemStyle: { color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{ offset: 0, color: '#38d6ff' }, { offset: 1, color: '#1753d4' }]), borderRadius: [5, 5, 0, 0] } }] });
  trendChart?.setOption({ grid: { left: 34, right: 14, top: 18, bottom: 28 }, xAxis: { type: 'category', data: (overview.value.trend || []).map((item) => item.date.slice(5)), axisLabel: { color: textColor, fontSize: 10 }, axisLine: { lineStyle: { color: gridColor } } }, yAxis: { type: 'value', minInterval: 1, splitLine: { lineStyle: { color: gridColor } }, axisLabel: { color: textColor, fontSize: 10 } }, series: [{ type: 'line', smooth: true, data: (overview.value.trend || []).map((item) => item.count), symbolSize: 7, lineStyle: { width: 3, color: '#fb59cb' }, itemStyle: { color: '#fb59cb' }, areaStyle: { color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{ offset: 0, color: 'rgba(251,89,203,.3)' }, { offset: 1, color: 'rgba(251,89,203,0)' }]) } }] });
  pieChart?.setOption({ series: [{ type: 'pie', radius: ['54%', '78%'], center: ['50%', '50%'], avoidLabelOverlap: true, label: { show: false }, data: [{ value: kpis.value.asset_reachable || 0, name: '在线', itemStyle: { color: '#39e5a2' } }, { value: Math.max((kpis.value.asset_total || 0) - (kpis.value.asset_reachable || 0), 0), name: '异常', itemStyle: { color: '#ef5b74' } }] }] });
}
async function toggleFullscreen() { try { if (!document.fullscreenElement) await document.documentElement.requestFullscreen(); else await document.exitFullscreen(); isFullscreen.value = !!document.fullscreenElement } catch { ElMessage.info('当前浏览器不支持全屏') } }
function resize() { assetChart?.resize(); trendChart?.resize(); pieChart?.resize() }
onMounted(() => { updateClock(); clockTimer = setInterval(updateClock, 1000); load(); refreshTimer = setInterval(load, 30000); window.addEventListener('resize', resize) })
onBeforeUnmount(() => { clearInterval(refreshTimer); clearInterval(clockTimer); assetChart?.dispose(); trendChart?.dispose(); pieChart?.dispose(); window.removeEventListener('resize', resize) })

const ScreenPanel = {
  props: { title: String, subtitle: String },
  template: '<section class="panel"><div class="panel-heading"><span>{{ title }}</span><small>{{ subtitle }}</small></div><div class="panel-body"><slot /></div></section>',
}

const MetricCard = {
  props: { icon: String, value: [String, Number], label: String, unit: String, tone: String },
  template: '<div class="metric-card" :class="tone"><span class="metric-icon">{{ icon }}</span><strong class="metric-value">{{ value }}<small>{{ unit }}</small></strong><span class="metric-label">{{ label }}</span></div>',
}
</script>

