de strong { max-width: 92px; overflow: hidden; color: #d7efff; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }.asset-node small { margin-top: 3px; color: #6f9bc2; font-size: 9px; }.asset-node.warning { border-color: #ffc04d; }.topology-legend { position: absolute; bottom: 10px; left: 16px; z-index: 4; display: flex; gap: 15px; color: #8caecc; font-size: 11px; }.topology-legend i { display: inline-block; width: 7px; height: 7px; margin-right: 4px; border-radius: 50%; }.green-dot { background: #39e5a2; }.yellow-dot { background: #ffc04d; }.red-dot { background: #ef5b74; }.rank-list { min-height: 180px; }.rank-row { position: relative; display: flex; align-items: center; gap: 8px; height: 28px; overflow: hidden; color: #9fc2df; font-size: 12px; }.rank-row i { display: grid; width: 17px; height: 17px; place-items: center; border-radius: 4px; color: #fff; background: #784eff; font-size: 10px; font-style: normal; }.rank-row span { z-index: 1; width: 45%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.rank-row b { z-index: 1; margin-left: auto; color: #ffd0f0; font-weight: 400; }.rank-row em { position: absolute; bottom: 2px; left: 25px; height: 4px; border-radius: 3px; background: linear-gradient(90deg, #e34ed4, #8b3fe9); }.empty-line { display: grid; min-height: 130px; place-items: center; color: #7094b8; font-size: 12px; }.mini-table { min-height: 178px; font-size: 11px; }.table-head, .table-row { display: grid; grid-template-columns: 1.15fr 1fr 42px; gap: 8px; align-items: center; padding: 8px 4px; border-bottom: 1px solid rgba(89, 149, 213, .17); }.table-head { color: #66a5d1; }.table-row { color: #a8c8e1; }.table-row span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.table-row b { font-weight: 400; }.ok { color: #39e5a2; }.bad { color: #ef5b74; }
